package io.github.jesterportfolio.hearth.combat;

import java.util.*;

/** 공개 보스 제어 시험의 콘텐츠. 수치와 위치는 운영 정책이 아닌 명시적 시험값입니다. */
public record CombatContent(String id,String title,double healthPerPlayer,double attack,long returnProtectionMillis,Revival revival,Retry retry,Exit exit,Path path,List<Pattern> patterns) {
    public CombatContent(String id,String title,double healthPerPlayer,double attack,long protection,Revival revival){this(id,title,healthPerPlayer,attack,protection,revival,null);}
    public CombatContent(String id,String title,double health,double attack,long protection,Revival revival,Retry retry){this(id,title,health,attack,protection,revival,retry,null);}
    public CombatContent(String id,String title,double health,double attack,long protection,Revival revival,Retry retry,Exit exit){this(id,title,health,attack,protection,revival,retry,exit,null);}
    public CombatContent(String id,String title,double health,double attack,long protection,Revival revival,Retry retry,Exit exit,Path path){this(id,title,health,attack,protection,revival,retry,exit,path,List.of());}
    public enum Shape { SPHERE,CONE,LINE,RING }
    public enum Technique { STRIKE,SLOW,REPEL }
    public enum Origin { LIVE,LOCKED }
    public record Pattern(String id,String title,double healthBelow,long intervalMillis,long windupMillis,double range,double damage,Shape shape,double width,double angle,double height,Origin origin,Technique technique,double strength,int effectTicks,int repeats,long repeatMillis){
        public Pattern(String id,String title,double health,long interval,long windup,double range,double damage,Shape shape,double width,double angle,double height,Origin origin){this(id,title,health,interval,windup,range,damage,shape,width,angle,height,origin,Technique.STRIKE,0,0,1,0);}
        public Pattern(String id,String title,double health,long interval,long windup,double range,double damage){this(id,title,health,interval,windup,range,damage,Shape.SPHERE,0,0,range,Origin.LIVE);}
        public Pattern{if(id==null||!id.matches("[a-z][a-z0-9_]{0,63}")||title==null||title.isBlank()||title.length()>80||!Double.isFinite(healthBelow)||healthBelow<=0||healthBelow>1||intervalMillis<100||intervalMillis>120000||windupMillis<0||windupMillis>30000||!Double.isFinite(range)||range<=0||range>32||!Double.isFinite(damage)||damage<=0||damage>32)throw new IllegalArgumentException("Invalid boss pattern");Objects.requireNonNull(shape);Objects.requireNonNull(origin);Objects.requireNonNull(technique);if(!Double.isFinite(strength)||strength<0||strength>1.5||effectTicks<0||effectTicks>200||repeats<1||repeats>4||repeatMillis<0||repeatMillis>2000||repeats>1&&repeatMillis<100||repeats==1&&repeatMillis!=0||technique==Technique.SLOW&&effectTicks<1||technique==Technique.REPEL&&strength<=0||technique==Technique.STRIKE&&(strength!=0||effectTicks!=0)||technique==Technique.SLOW&&strength!=0||technique==Technique.REPEL&&effectTicks!=0)throw new IllegalArgumentException("Invalid boss skill");if(!Double.isFinite(width)||!Double.isFinite(angle)||!Double.isFinite(height)||height<=0||height>32||switch(shape){case SPHERE->width!=0||angle!=0||height!=range;case CONE->width!=0||angle<=0||angle>180;case LINE->width<=0||width>range*2||angle!=0;case RING->width<=0||width>=range||angle!=0;})throw new IllegalArgumentException("Invalid boss area");}
    }
    public enum Pool { PERSONAL,SHARED }
    public enum LocationMode { DEATH,START,FIXED }
    public record Pose(UUID world,double x,double y,double z,float yaw,float pitch) {
        public Pose {Objects.requireNonNull(world);if(!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(z)||!Float.isFinite(yaw)||!Float.isFinite(pitch))throw new IllegalArgumentException("Invalid combat pose");}
    }
    public record Effect(String type,int amplifier,int ticks) {
        public Effect {if(!Set.of("RESISTANCE","REGENERATION","SLOWNESS").contains(type)||amplifier<0||amplifier>4||ticks<1||ticks>1200)throw new IllegalArgumentException("Invalid combat effect");}
    }
    public record Revival(boolean enabled,String condition,Pool pool,int limit,double healthFraction,LocationMode location,FieldContent.Point fixed,List<Effect> effects) {
        public Revival {effects=List.copyOf(effects);Objects.requireNonNull(pool);Objects.requireNonNull(location);if(condition==null||!condition.matches("[a-z][a-z0-9_]{0,63}")||limit<0||limit>32||!Double.isFinite(healthFraction)||healthFraction<=0||healthFraction>1||effects.size()>4||(location==LocationMode.FIXED)!=(fixed!=null))throw new IllegalArgumentException("Invalid combat revival");}
    }
    /** 미등록은 자동 재도전 불가. 재도전의 위치/회복값은 제작자가 명시합니다. */
    public record Retry(String scope,FieldContent.Point entry,float yaw,float pitch,double healthFraction,List<Effect> effects,FieldReset reset){
        public Retry(String scope,FieldContent.Point entry,float yaw,float pitch,double health,List<Effect> effects){this(scope,entry,yaw,pitch,health,effects,null);}
        public Retry{effects=List.copyOf(effects);if(!Set.of("BOSS_ONLY","FROM_PATH").contains(scope)||("FROM_PATH".equals(scope))!=(reset!=null)||entry==null||!Float.isFinite(yaw)||!Float.isFinite(pitch)||Math.abs(pitch)>90||!Double.isFinite(healthFraction)||healthFraction<=0||healthFraction>1||effects.size()>4)throw new IllegalArgumentException("Invalid or unsupported combat retry policy");}
        public Pose pose(UUID world){return new Pose(world,entry.x(),entry.y(),entry.z(),yaw,pitch);}
    }
    /** 미등록이면 종료 복귀를 자동 생성하지 않습니다. 위치·회복값은 공개 시험 콘텐츠의 명시값입니다. */
    public record Exit(FieldContent.Point entry,float yaw,float pitch,double healthFraction,List<Effect> effects){
        public Exit{effects=List.copyOf(effects);new Retry("BOSS_ONLY",entry,yaw,pitch,healthFraction,effects);}
        public Pose pose(UUID world){return new Pose(world,entry.x(),entry.y(),entry.z(),yaw,pitch);}
    }
    public record Path(CombatContent combat,FieldContent.Box gathering,Exit bossEntry,Retry retry,Checkpoint checkpoint,List<Checkpoint> checkpoints,Route route){
        public Path(CombatContent c,FieldContent.Box b,Exit e,Retry r,Checkpoint cp,List<Checkpoint> points){this(c,b,e,r,cp,points,null);}
        public Path(CombatContent combat,FieldContent.Box gathering,Exit bossEntry){this(combat,gathering,bossEntry,null,null,List.of());}
        public Path(CombatContent c,FieldContent.Box b,Exit e,Retry r){this(c,b,e,r,null,List.of());}
        public Path(CombatContent c,FieldContent.Box b,Exit e,Retry r,Checkpoint cp){this(c,b,e,r,cp,cp==null?List.of():List.of(cp));}
        public Path{checkpoints=List.copyOf(checkpoints);if(checkpoints.size()>16||checkpoints.stream().map(Checkpoint::id).distinct().count()!=checkpoints.size()||checkpoint==null&&!checkpoints.isEmpty()||checkpoint!=null&&!checkpoints.contains(checkpoint))throw new IllegalArgumentException("Invalid checkpoint selection");Objects.requireNonNull(combat);Objects.requireNonNull(gathering);Objects.requireNonNull(bossEntry);if(route!=null&&!route.validCheckpoints(checkpoints))throw new IllegalArgumentException("Unknown route checkpoint");if(retry!=null&&!retry.scope().equals("FROM_PATH")||combat.path()!=null||combat.retry()!=null||combat.exit()!=null||!combat.patterns().isEmpty())throw new IllegalArgumentException("Nested path policy is not supported");}
    }
    /** 같은 길목 도전 안의 순서 있는 이동 구간. 도전/부활 예산을 새로 만들지 않습니다. */
    public record Section(String id,String title,FieldContent.Box gathering,Exit nextEntry,String checkpoint){
        public Section{if(id==null||!id.matches("[a-z][a-z0-9_]{0,63}")||id.equals("boss_gate")||title==null||title.isBlank()||title.length()>80||checkpoint!=null&&!checkpoint.matches("[a-z][a-z0-9_]{0,63}"))throw new IllegalArgumentException("Invalid path section");Objects.requireNonNull(gathering);Objects.requireNonNull(nextEntry);if(nextEntry.healthFraction()!=1||!nextEntry.effects().isEmpty())throw new IllegalArgumentException("Route entry does not define recovery");}
    }
    public record Route(List<Section> sections,String restartSection){
        public Route{sections=List.copyOf(sections);if(sections.isEmpty()||sections.size()>8||sections.stream().map(Section::id).distinct().count()!=sections.size()||restartSection==null||!restartSection.equals("boss_gate")&&sections.stream().noneMatch(s->s.id().equals(restartSection)))throw new IllegalArgumentException("Invalid path route");}
        public int restartIndex(){return restartSection.equals("boss_gate")?sections.size():java.util.stream.IntStream.range(0,sections.size()).filter(i->sections.get(i).id().equals(restartSection)).findFirst().orElseThrow();}
        boolean validCheckpoints(List<Checkpoint> points){return sections.stream().allMatch(s->s.checkpoint()==null||points.stream().anyMatch(p->p.id().equals(s.checkpoint())));}
    }
    private static Route route(Map<?,?> r){if(!(r.get("sections") instanceof List<?> rows))throw new IllegalArgumentException("Missing route sections");var sections=new ArrayList<Section>();for(var value:rows){var row=map(value);var a=map(row.get("gathering"));var p=map(row.get("next-entry"));sections.add(new Section(text(row,"id"),text(row,"title"),new FieldContent.Box(number(a,"min-x"),number(a,"max-x"),number(a,"min-y"),number(a,"max-y"),number(a,"min-z"),number(a,"max-z")),new Exit(new FieldContent.Point(number(p,"x"),number(p,"y"),number(p,"z")),(float)number(p,"yaw"),(float)number(p,"pitch"),1,List.of()),row.containsKey("checkpoint")?text(row,"checkpoint"):null));}return new Route(sections,text(r,"restart-section"));}
    public record Checkpoint(String id,String quest,FieldContent.Box area,Exit entry){public Checkpoint{if(id==null||quest==null||!id.matches("[a-z][a-z0-9_]{0,63}")||!quest.matches("[a-z][a-z0-9_]{0,63}"))throw new IllegalArgumentException("Invalid checkpoint");Objects.requireNonNull(area);Objects.requireNonNull(entry);}}
    private static Checkpoint checkpoint(Map<?,?> r){var a=map(r.get("area"));return new Checkpoint(text(r,"id"),text(r,"quest"),new FieldContent.Box(number(a,"min-x"),number(a,"max-x"),number(a,"min-y"),number(a,"max-y"),number(a,"min-z"),number(a,"max-z")),exit(map(r.get("entry"))));}
    public CombatContent {patterns=List.copyOf(patterns);if(patterns.size()>8||patterns.stream().map(Pattern::id).distinct().count()!=patterns.size()||!patterns.isEmpty()&&patterns.getFirst().healthBelow()!=1)throw new IllegalArgumentException("Invalid boss pattern list");for(int i=1;i<patterns.size();i++)if(patterns.get(i).healthBelow()>=patterns.get(i-1).healthBelow())throw new IllegalArgumentException("Unordered boss phases");Objects.requireNonNull(revival);if(retry!=null&&retry.scope().equals("FROM_PATH")&&path==null)throw new IllegalArgumentException("Path retry requires path content");if(id==null||!id.matches("[a-z][a-z0-9_]{0,63}")||title==null||title.isBlank()||title.length()>80||!Double.isFinite(healthPerPlayer)||healthPerPlayer<1||healthPerPlayer>256||!Double.isFinite(attack)||attack<0||attack>32||returnProtectionMillis<0||returnProtectionMillis>30000)throw new IllegalArgumentException("Invalid combat content");}
    public static CombatContent parse(Map<?,?> root){if(!(root.get("format") instanceof Number f)||f.doubleValue()!=1)throw new IllegalArgumentException("Invalid combat format");var r=map(root.get("revival"));if(!(r.get("enabled") instanceof Boolean enabled))throw new IllegalArgumentException("Invalid combat enabled flag");var effects=new ArrayList<Effect>();if(!(r.get("effects") instanceof List<?> raw))throw new IllegalArgumentException("Invalid combat effects");for(Object e:raw){var m=map(e);effects.add(new Effect(text(m,"type"),integer(m,"amplifier"),integer(m,"ticks")));}FieldContent.Point fixed=null;if(r.containsKey("fixed")){var p=map(r.get("fixed"));fixed=new FieldContent.Point(number(p,"x"),number(p,"y"),number(p,"z"));}return new CombatContent(text(root,"id"),text(root,"title"),number(root,"health-per-player"),number(root,"attack"),integer(root,"return-protection-ms"),new Revival(enabled,text(r,"condition"),Pool.valueOf(text(r,"pool")),integer(r,"limit"),number(r,"health-fraction"),LocationMode.valueOf(text(r,"location")),fixed,effects),root.containsKey("retry")?retry(map(root.get("retry"))):null,root.containsKey("exit")?exit(map(root.get("exit"))):null,root.containsKey("path")?path(map(root.get("path"))):null,patterns(root));}
    private static List<Pattern> patterns(Map<?,?> root){
        if(!root.containsKey("patterns"))return List.of();if(!(root.get("patterns") instanceof List<?> rows))throw new IllegalArgumentException("Invalid patterns");var result=new ArrayList<Pattern>();
        for(var row:rows){var p=map(row);var shape=p.containsKey("shape")?Shape.valueOf(text(p,"shape")):Shape.SPHERE;var origin=p.containsKey("origin")?Origin.valueOf(text(p,"origin")):Origin.LIVE;
            if(shape!=Shape.LINE&&shape!=Shape.RING&&p.containsKey("width")||shape!=Shape.CONE&&p.containsKey("angle")||shape==Shape.SPHERE&&p.containsKey("height"))throw new IllegalArgumentException("Unsupported area property");
            double range=number(p,"range");result.add(new Pattern(text(p,"id"),text(p,"title"),number(p,"health-below"),integer(p,"interval-ms"),integer(p,"windup-ms"),range,number(p,"damage"),shape,shape==Shape.LINE||shape==Shape.RING?number(p,"width"):0,shape==Shape.CONE?number(p,"angle"):0,shape==Shape.SPHERE?range:number(p,"height"),origin,p.containsKey("technique")?Technique.valueOf(text(p,"technique")):Technique.STRIKE,p.containsKey("strength")?number(p,"strength"):0,p.containsKey("effect-ticks")?integer(p,"effect-ticks"):0,p.containsKey("repeats")?integer(p,"repeats"):1,p.containsKey("repeat-ms")?integer(p,"repeat-ms"):0));}return result;
    }
    private static Path path(Map<?,?> r){
        var stage=map(r.get("combat"));if(stage.containsKey("path")||stage.containsKey("retry")||stage.containsKey("exit"))throw new IllegalArgumentException("Nested path definition");var area=map(r.get("gathering"));var points=new ArrayList<Checkpoint>();Checkpoint selected=null;
        if(r.containsKey("checkpoint")){if(r.containsKey("checkpoints")||r.containsKey("restart-checkpoint"))throw new IllegalArgumentException("Ambiguous checkpoint definition");selected=checkpoint(map(r.get("checkpoint")));points.add(selected);}
        else if(r.containsKey("checkpoints")){if(!(r.get("checkpoints") instanceof List<?> rows)||rows.isEmpty())throw new IllegalArgumentException("Invalid checkpoints");for(var row:rows)points.add(checkpoint(map(row)));String id=text(r,"restart-checkpoint");selected=points.stream().filter(p->p.id().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Unknown restart checkpoint"));}
        else if(r.containsKey("restart-checkpoint"))throw new IllegalArgumentException("Missing checkpoints");
        return new Path(parse(stage),new FieldContent.Box(number(area,"min-x"),number(area,"max-x"),number(area,"min-y"),number(area,"max-y"),number(area,"min-z"),number(area,"max-z")),exit(map(r.get("boss-entry"))),r.containsKey("retry")?retry(map(r.get("retry"))):null,selected,points,r.containsKey("route")?route(map(r.get("route"))):null);
    }
    private static Exit exit(Map<?,?> r){var copy=new HashMap<Object,Object>(r);copy.put("scope","BOSS_ONLY");var p=retry(copy);return new Exit(p.entry(),p.yaw(),p.pitch(),p.healthFraction(),p.effects());}
    private static Retry retry(Map<?,?> r){var p=map(r.get("entry"));var effects=new ArrayList<Effect>();if(!(r.get("effects") instanceof List<?> raw))throw new IllegalArgumentException("Missing retry effects");for(Object e:raw){var m=map(e);effects.add(new Effect(text(m,"type"),integer(m,"amplifier"),integer(m,"ticks")));}return new Retry(text(r,"scope"),new FieldContent.Point(number(p,"x"),number(p,"y"),number(p,"z")),(float)number(p,"yaw"),(float)number(p,"pitch"),number(r,"health-fraction"),effects,r.containsKey("reset")?FieldReset.parse(map(r.get("reset"))):null);}
    private static Map<?,?> map(Object o){if(!(o instanceof Map<?,?> m))throw new IllegalArgumentException("Invalid combat mapping");return m;}
    private static String text(Map<?,?> m,String k){if(!(m.get(k) instanceof String s))throw new IllegalArgumentException("Invalid combat text");return s;}
    private static double number(Map<?,?> m,String k){if(!(m.get(k) instanceof Number n)||!Double.isFinite(n.doubleValue()))throw new IllegalArgumentException("Invalid combat number");return n.doubleValue();}
    private static int integer(Map<?,?> m,String k){double n=number(m,k);if(n!=(int)n)throw new IllegalArgumentException("Invalid combat integer");return (int)n;}
}
